<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {Plus,MessageCircle,FileText,Info,Film,HelpCircle,Pencil,Trash2,ArrowUp,ArrowDown} from 'lucide-svelte';
 import {contentModuleTypes,type ContentModuleType,type ContentModule} from './types';
 import {MAX_CONTENT_MODULES,contentModuleName,contentModuleReady,reorderContentModule} from './content';
 import type {AdventureChat} from '../chat/editor';
 let {modules,chats=[],loading=false,showAdd=true,addDisabled=false,onadd,onedit,onchange}:{modules:ContentModule[];chats?:AdventureChat[];loading?:boolean;showAdd?:boolean;addDisabled?:boolean;onadd:(type:ContentModuleType)=>void;onedit:(id:string)=>void;onchange:(modules:ContentModule[])=>void}=$props();
 let selected=$state<ContentModuleType>('chat');
 function move(from:number,to:number){onchange(reorderContentModule(modules,from,to));}
</script>
<section class="entity-modules" aria-label={ui.text("Módulos del elemento")}>

 {#if showAdd}<div class="module-add"><label>{ui.text("Tipo de módulo")}<select aria-label={ui.text("Tipo de módulo")} bind:value={selected} disabled={loading}>{#each contentModuleTypes as type}<option value={type.id}>{ui.text(type.label??'')}</option>{/each}</select></label><button class="add" onclick={()=>onadd(selected)} disabled={loading||addDisabled||modules.length>=MAX_CONTENT_MODULES}><Plus size={16}/> {ui.text("Añadir")}</button></div>{/if}
 <div class="module-list" role="list" aria-label={ui.text("Módulos añadidos")}>
 {#each modules as module,i (module.id)}{@const name=contentModuleName(module,chats,ui.text('Conversación'))}
 <div class="module-wrap"><article class="module-card" role="listitem" aria-label={'Módulo '+name}><span class="module-icon">{#if module.type==='chat'}<MessageCircle size={20}/>{:else if module.type==='info'}<Info size={20}/>{:else if module.type==='video'}<Film size={20}/>{:else if module.type==='question'}<HelpCircle size={20}/>{:else}<FileText size={20}/>{/if}</span><div class="module-name"><strong>{i+1}. {name}</strong><small>{ui.text(contentModuleTypes.find(type=>type.id===module.type)?.label??'')}{contentModuleReady(module,chats)?'':ui.text(' · Pendiente')}</small></div><div class="module-actions"><button disabled={loading||i===0} onclick={()=>move(i,i-1)} aria-label={ui.text("Subir módulo ")+name} title={ui.text("Subir")}><ArrowUp size={15}/></button><button disabled={loading||i===modules.length-1} onclick={()=>move(i,i+1)} aria-label={ui.text("Bajar módulo ")+name} title={ui.text("Bajar")}><ArrowDown size={15}/></button><button data-edit-module={module.id} disabled={loading} onclick={()=>onedit(module.id)} aria-label={ui.text("Editar módulo ")+name} title={ui.text("Editar")}><Pencil size={17}/></button><button class="delete" disabled={loading} onclick={()=>onchange(modules.filter(m=>m.id!==module.id))} aria-label={ui.text("Eliminar módulo ")+name} title={ui.text("Eliminar")}><Trash2 size={17}/></button></div></article>
</div>
 {:else}<p class="empty">{ui.text("Elige un tipo y pulsa Añadir. Los módulos se reproducen en orden.")}</p>{/each}
 </div>{#if loading}<p class="loading" role="status">{ui.text("Abriendo módulo…")}</p>{/if}
</section>
<style>
 .entity-modules{padding:4px 0}.module-add{display:flex;align-items:flex-end;gap:8px;padding:10px 0 18px;border-bottom:1px solid #e2e9db}label{display:flex;flex-direction:column;gap:7px;flex:1;min-width:0;color:#62755c;font-size:12px;font-weight:600}select{width:100%;box-sizing:border-box;border:1px solid #d5dfce;border-radius:7px;background:white;padding:10px;font:inherit;font-weight:400;color:#35502f;min-width:0}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid #d5dfce;border-radius:7px;padding:9px;background:white;color:#35502f;font:inherit;font-size:12px;cursor:pointer}button:disabled{opacity:.4;cursor:default}button:hover:not(:disabled){background:#eef3e8}.add{height:38px;flex-shrink:0;background:#dfeccd}.module-list{display:flex;flex-direction:column;gap:10px;padding-top:18px}.module-wrap{min-width:0}.module-card{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid #d5dfce;border-radius:10px;background:white;min-width:0}.module-icon{display:grid;place-items:center;flex-shrink:0;width:34px;height:34px;border-radius:8px;background:#edf2e7;color:#52694a}.module-name{display:flex;flex-direction:column;gap:4px;flex:1;min-width:40px}.module-name strong{font-size:13px;color:#35502f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.module-name small{font-size:11px;color:#718269}.module-actions{display:flex;gap:5px;flex-shrink:0}.module-actions button{width:32px;height:32px;padding:0}.module-actions .delete{color:#a66754}.empty,.loading{font-size:12px;line-height:1.6;color:#718269;margin:0}.loading{margin-top:12px}button:focus-visible,select:focus-visible{outline:2px solid #789557;outline-offset:2px}@media(max-width:400px){.module-wrap{min-width:0}.module-card{gap:7px;padding:10px}.module-icon{width:28px;height:28px}.module-actions{gap:3px}.module-actions button{width:30px}}
</style>
